+import type { SessionEvent } from '../types.ts';
+
+// What a run changed in one file: the added and removed lines of its diff.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Rule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type Finding = { rule: Rule; path: string; line?: string };
+
+const TEST_FILE = /(\.(test|spec)\.[^/]+$|_test\.[^/]+$|(^|\/)test_[^/]*$|(^|\/)tests?\/)/;
+const CODE_FILE = /\.(m?[jt]sx?|c?[jt]sx?|py|go|rs|rb|java|kt|cs|php|cc|cpp|c|h|hpp|swift|sh)$/;
+const ASSERT = /\bexpect\(|\bassert\w*|\.should\b/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bx(it|test|describe)\(|\bt\.Skip(Now|f)?\(|pytest\.mark\.skip|#\[ignore\]/;
+const CONTENT: [Rule, RegExp][] = [
+  ['suppression', /@ts-(ignore|expect-error|nocheck)|eslint-disable|# type: ignore|# noqa|# pylint: disable|#\[allow\(/],
+  ['swallowed-error', /catch\s*(\(\w*\))?\s*\{\s*\}|^\s*except\b.*:\s*pass\s*$/],
+  ['type-escape', /\bas any\b/],
+  ['stub', /not implemented|NotImplementedError|unimplemented!\(|todo!\(/i],
+];
+
+const count = (lines: string[], re: RegExp) => lines.filter((l) => re.test(l)).length;
+
+function testFindings(c: FileChange): Finding[] {
+  if (!TEST_FILE.test(c.path)) return [];
+  if (c.deleted) return [{ rule: 'test-deleted', path: c.path }];
+  const out: Finding[] = [];
+  if (count(c.removed, ASSERT) > count(c.added, ASSERT)) out.push({ rule: 'test-weakened', path: c.path });
+  for (const line of c.added) if (SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, line: line.trim() });
+  return out;
+}
+
+function contentFindings(c: FileChange): Finding[] {
+  if (!CODE_FILE.test(c.path)) return [];
+  return c.added.flatMap((line) => CONTENT.filter(([, re]) => re.test(line)).map(([rule]) => ({ rule, path: c.path, line: line.trim() })));
+}
+
+// Shortcuts that make work look done. A finding is a flag, not a verdict: the model may explain it.
+export function findSlop(changes: FileChange[]): Finding[] {
+  return changes.flatMap((c) => [...testFindings(c), ...contentFindings(c)]);
