+++ b/src/core/trust/slop.ts	2026-11-04 07:38:11.707677859 +0000
@@ -0,0 +1,51 @@
+// What a run's changes look like, per file: the added and removed lines, and whether the file was deleted.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; line?: string };
+
+const PROSE = /\.(md|mdx|txt|rst)$/;
+const TEST_FILE = /(\.test\.|\.spec\.|_test\.|(^|\/)tests?\/|(^|\/)test_[^/]*\.py$)/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|expect-error)|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|^except\b.*:\s*pass$/],
+  ['type-escape', /\bas any\b|:\s*any\b/],
+  ['stub', /not implemented|NotImplementedError|todo!\(\)|unimplemented!\(\)/i],
+];
+const TEST_SKIP = /\.skip\(|\bx(it|describe|test)\(|t\.Skip\(|@pytest\.mark\.skip|pytest\.skip\(|@unittest\.skip|self\.skipTest\(/;
+const ASSERT = /\bexpect\(|\bassert/;
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (PROSE.test(c.path)) continue;
+    const test = TEST_FILE.test(c.path);
+    for (const added of c.added) {
+      const line = added.trim();
+      for (const [rule, re] of LINE_RULES) if (re.test(line)) out.push({ rule, path: c.path, line });
+      if (test && TEST_SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, line });
+    }
+    if (!test) continue;
+    if (c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    else if (c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+  }
+  return out;
+}
+
+// Reads `git diff -U0` text. Header lines come before the first @@ of a file; after it, +/- lines are content.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      cur = { path: line.slice(line.lastIndexOf(' b/') + 3), added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) {
+      if (line.startsWith('deleted file mode')) cur.deleted = true;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
