diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/pricing-rules.test.ts b/test/pricing-rules.test.ts
--- a/test/pricing-rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/pricing-rules.test.ts	2026-11-04 07:34:43.255665468 +0000
@@ -0,0 +1,32 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules and region table in README.md.
+describe('pricing rules', () => {
+  test('10 units of one SKU get the 5% bulk tier', () => {
+    // 10 pens = 1200; 5% = 60 -> 1140; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('50 units of one SKU get the 10% bulk tier', () => {
+    // 50 pens = 6000; 10% = 600 -> 5400; free shipping; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same SKU are merged before bulk tiers apply', () => {
+    // 5 + 5 pens = 10 units -> 5% off, same as the single line above
+    expect(totals(cart('US', [['PEN', 5], ['PEN', 5]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('shipping threshold is checked after the coupon', () => {
+    // 2 bags + 2 mugs = 5300; SAVE10 -> 4770, below 5000, so shipping is charged
+    // tax 7% of 5570 = 389.9 -> 390
+    expect(totals(cart('US', [['BAG', 2], ['MUG', 2]], 'SAVE10'))).toMatchObject({ subtotal: 5300, coupon: 530, shipping: 800, tax: 390, total: 5960 });
+  });
+
+  test('UK ships free from 4000', () => {
+    // 1 bag + 4 mugs = 4000 exactly; tax 20% = 800
+    expect(totals(cart('UK', [['BAG', 1], ['MUG', 4]]))).toMatchObject({ subtotal: 4000, shipping: 0, tax: 800, total: 4800 });
+  });
+});

