-  throw new Error('not implemented');
+  const slug = text
+    .toLowerCase()
+    .normalize('NFD')
+    .replace(/\p{M}/gu, '')
+    .replace(/[ßæœøłđ]/g, (c) => LETTERS[c])
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-|-$/g, '');
+  if (max === undefined || slug.length <= max) {
+    return slug;
+  }
+  const cut = slug.slice(0, max + 1).lastIndexOf('-');
